using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Arith.CharacterSums;

internal sealed class PascadiOriginalWeightAverageDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Original integer parameter incidence for averaging the physical rational multiplicity. A short unit vector identifies the entire congruence lattice, so the count includes all actual slope lifts without an extra factor p.",
        H("Original parameter incidence and short vectors"),
        Blocks(
            Paragraph(Text("Write Q(u,z)=(Y/X)u^2+(X/Y)z^2 and H^2=XY, with X,Y,H positive. The actual index-c lattice is c divides w*z-t*u, inside the literal integer rectangle |u|<=X, |z|<=Y. A ReducedMiddleBasis is an actual basis with its shortest-vector law and centered reduction. This module proves the geometric and congruence ingredients and their finite dyadic summation over the original integer parameters.")),
            Describe.Lean(DescribeId.Create("pascadi-actual-middle-box-section-count"),
                DeclarationHandle.Create("D5/S3/Arith/CharacterSums/PascadiOriginalWeightAverage.actual_middle_box_section_count"),
                H("Count the actual lattice section"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive c, any reduced actual basis B, and any finite set s of actual integer points of this lattice in the literal rectangle, card(s)<=16(1+H/sigma+XY/c), where sigma=sqrt(Q(B.R)). No counting injection is assumed.")),
                    Paragraph(Text("Decompose each actual point in B. The proved coordinate square bounds imply |i|<=2H/sigma and |j|<=2H*sigma/c. Count the resulting integer rectangle and its image under the physical basis map. Reduction gives sigma^2<2c, absorbing the second boundary term into H/sigma. The remaining product term is exactly proportional to the physical area divided by the determinant."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("pascadi-middle-lattice-unit-vector-identity"),
                DeclarationHandle.Create("D5/S3/Arith/CharacterSums/PascadiOriginalWeightAverage.middleLattice_eq_of_unit_vector"),
                H("A unit vector fixes the actual lattice"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("If w and U.1 are units modulo c and the actual integer vector U lies in the lattice c divides w*z-t*u, then that lattice equals the lattice c divides U.1*z-U.2*u.")),
                    Paragraph(Text("The original membership gives w*U.2=t*U.1 modulo c. Multiplying either determinant relation by the appropriate unit, applying this identity, and cancelling the unit proves both inclusions for actual integer vectors. There is no separate selection of a slope representative."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("pascadi-original-short-vector-incidence-count"),
                DeclarationHandle.Create("D5/S3/Arith/CharacterSums/PascadiOriginalWeightAverage.original_short_vector_incidence_count"),
                H("Count original parameters incident to one shortest vector"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Fix nonzero c, positive X,Y,H with H^2=XY, and one nonzero actual integer vector U whose first coordinate is a unit modulo c. A finite set of original parameter vectors (w,t) in the literal rectangle, each with unit w, each containing U in its actual lattice and having U shortest, has cardinality at most 16(1+H/sqrt(Q(U))+XY/c).")),
                    Paragraph(Text("The unit-vector identity makes all these actual lattices identical to the one determined by U. Choose an actual reduced basis for that lattice using the previously proved existence theorem. In the nonempty case the shortest-vector laws identify its squared first-vector length with Q(U). Antisymmetry of the integer determinant puts every original (w,t) into this fixed lattice; the actual box-section theorem counts these integer parameters directly. This already includes all full slopes arising from the original rectangle."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("pascadi-short-middle-vector-unit-coordinates"),
                DeclarationHandle.Create("D5/S3/Arith/CharacterSums/PascadiOriginalWeightAverage.short_middle_vector_unit_coordinates"),
                H("Short vectors have two nonzero unit coordinates"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Let p be prime, 0<X<=Y, Y<p^3 and XY<2p^4, and let t,w be units modulo p^2. Any nonzero actual vector U of their index-p^2 lattice with Q(U)<=XY/p^2 has both coordinates nonzero and both coordinates units modulo p^2.")),
                    Paragraph(Text("An axis vector has its nonzero coordinate divisible by p^2. The norm bound and Y<p^3 exclude this. If both nonzero coordinates were divisible by p, then Q(U)>=2|U.1*U.2|>=2p^2, contradicting XY<2p^4. The original unit slope transfers divisibility by p between the coordinates, so neither coordinate is divisible by p. The prime-power unit criterion then gives both unit claims. The displayed cutoffs are explicit sufficient hypotheses, not silently inferred original-range assumptions."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("pascadi-nonaxis-short-vector-candidates-count"),
                DeclarationHandle.Create("D5/S3/Arith/CharacterSums/PascadiOriginalWeightAverage.nonaxis_short_vector_candidates_count"),
                H("Count nonaxis short-vector candidates without a perimeter term"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For positive X,Y,H with H^2=XY and R>=0, every finite set of actual integer vectors with both coordinates nonzero and Q(U)<=R^2 has cardinality at most 4R^2.")),
                    Paragraph(Text("The weighted ball lies in the anisotropic rectangle of half-widths RX/H and RY/H, whose product is R^2. Since both coordinates are nonzero, erase zero from each symmetric integer interval before multiplying the counts. Each remaining interval has at most twice its half-width, giving 4R^2 with no perimeter term."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("pascadi-actual-shortest-vector-scale-count"),
                DeclarationHandle.Create("D5/S3/Arith/CharacterSums/PascadiOriginalWeightAverage.actual_shortest_vector_scale_count"),
                H("One actual shortest-vector scale"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Keep the prime, width and cutoff hypotheses above. For each original parameter wt in a finite set s in the literal box, choose the first vector U(wt) of an actual reduced index-p^2 basis. Suppose both original parameters are units modulo p^2 and R^2<=Q(U(wt))<=4R^2, with Q(U(wt))<=XY/p^2 and R>0. Then card(s)<=256R^2(1+H/R+XY/p^2).")),
                    Paragraph(Text("Short-vector exclusion gives two unit coordinates for every candidate U. Count their actual image by the nonaxis ball bound at radius 2R, obtaining at most 16R^2 candidates. Partition the original integer parameters by their chosen vector. The proved original incidence count bounds each fiber by 16(1+H/sqrt(Q(U))+XY/p^2), at most 16(1+H/R+XY/p^2). Sum these actual fibers. The actual reduced bases supply all shortest-vector facts; no fiber-count supplier is assumed."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("pascadi-actual-shortest-vector-scale-weight"),
                DeclarationHandle.Create("D5/S3/Arith/CharacterSums/PascadiOriginalWeightAverage.actual_shortest_vector_scale_weight"),
                H("Physical multiplicity of one shortest-vector scale"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Under the preceding actual scale hypotheses and R<=H/p, the sum over s of 1+H/(p*sqrt(Q(U(wt)))) is at most 512(H/p)(R+H+(XY/p^2)R).")),
                    Paragraph(Text("The lower scale bound makes each physical weight at most 1+H/(pR), at most 2H/(pR) since R<=H/p. Multiply this bound by the proved actual scale count and simplify. The scale-independent term is (XY)/p, and the remaining terms are proportional to R, ready for the geometric summation."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("pascadi-actual-physical-weight-average"),
                DeclarationHandle.Create("D5/S3/Arith/CharacterSums/PascadiOriginalWeightAverage.actual_physical_weight_average"),
                H("Average the actual physical rational multiplicity"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Let p be prime, 1<=X<=Y, Y<p^3, XY<2p^4, H>0, H^2=XY and p<=H. For each original integer parameter wt in any finite set s in the literal rectangle, suppose both coordinates are units modulo p^2 and choose U(wt) as the first vector of an actual reduced index-p^2 basis. With A=XY, the sum of 1+H/(p*sqrt(Q(U(wt)))) is at most 2048[A+(A/p)(1+log(2p)/log(2))+A^2/p^4]. Existence of the required actual reduced bases was proved in PascadiOriginalLattice; no incidence count or parameter injection is supplied as a hypothesis.")),
                    Paragraph(Text("Put T=H/p>=1 and choose an integer N with 2^N<=T<2^(N+1). Above norm T, each weight is at most 2 and the original rectangle contains at most 9A integer parameters, giving 18A. At smaller norms, the proved nonaxis exclusion gives length at least 1. Every actual shortest vector is therefore in a dyadic scale 2^k<=sigma<2^(k+1) with k<=N. A finite indicator-sum argument covers the original parameters by these actual scales without assuming a partition or injection.")),
                    Paragraph(Text("Apply the proved physical scale bound at every k. The geometric sum of the scale lengths is at most 2T. The cutoff A<2p^4 gives T<2p, so the number of scales N+1 is at most 1+log(2p)/log(2). Summing gives 18A+1024A/p^2+512(A/p)(N+1)+1024A^2/p^4, which implies the displayed bound. Every candidate and incidence count concerns actual integer (w,t); there is no extra factor p from a freely selected slope lift."))),
                DescribeRole.Theorem),
            Paragraph(Text("Application boundary: the full physical-weight average is established under the stated explicit hypotheses for actual reduced bases. To apply it to the original prime-cube theorem one must check these width and size conditions in its parameter range and combine it with the original record counts, singular and exceptional charts, and exact reconstruction. The complete prime-cube six-tuple bound is not established by this module alone.")))));
}
